/*
 Devfolio Studio — Phase 0, dependency-free reference prototype.
 This is intentionally NOT the hosted SaaS, and NOT a Puck integration.
 The saved schema and shared renderer demonstrate B1 editing semantics while
 package installation is unavailable. See docs/PHASE0_VALIDATION.md.
*/
(()=>{
'use strict';
const STORAGE='devfolio.phase0.draft.v1';
const PUBLISHED='devfolio.phase0.published.v1';
const ALLOWED=['Hero','SectionHeading','ProjectGrid','About','SkillCloud','Freeform','Contact','Text','Image','Spacer'];
const BLOCK_INFO={
 Hero:{title:'Hero section',icon:'layout',group:'Portfolio',hint:'Introduce yourself'},
 SectionHeading:{title:'Section heading',icon:'type',group:'Basic',hint:'Title and description'},
 ProjectGrid:{title:'Project grid',icon:'grid',group:'Portfolio',hint:'Connected to projects'},
 About:{title:'About section',icon:'user',group:'Portfolio',hint:'Your personal story'},
 SkillCloud:{title:'Skills list',icon:'grid',group:'Portfolio',hint:'Connected to skills'},
 Freeform:{title:'Freeform section',icon:'move',group:'Layout',hint:'Move and resize cards'},
 Contact:{title:'Contact section',icon:'link',group:'Portfolio',hint:'Share contact details'},
 Text:{title:'Text block',icon:'type',group:'Basic',hint:'Heading and body copy'},
 Image:{title:'Image',icon:'image',group:'Basic',hint:'Upload or paste URL'},
 Spacer:{title:'Spacer',icon:'layout',group:'Layout',hint:'Add breathing room'}
};
const ICON=(name,cls='')=>`<svg aria-hidden="true" class="icon ${cls}"><use href="#i-${name}"></use></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=(obj)=>JSON.parse(JSON.stringify(obj));
const clamp=(value,min,max)=>Math.min(max,Math.max(min,Number(value)||0));
const id=()=>`b-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const url=(s)=>{try{const v=String(s||'').trim();if(!v)return '';if(v.startsWith('data:image/png;')||v.startsWith('data:image/jpeg;')||v.startsWith('data:image/webp;'))return v;const u=new URL(v);return ['https:','http:','mailto:'].includes(u.protocol)?v:'';}catch{return ''}};
const webUrl=(s)=>{const v=url(s);return /^https?:/i.test(v)?v:''};
const mailUrl=(s)=>/^\S+@\S+\.\S+$/.test(String(s||'').trim())?'mailto:'+String(s).trim():'';
const txt=(label,key,value,scope='site',placeholder='')=>`<div class="field"><label>${esc(label)}</label><input type="text" data-${scope}-field="${esc(key)}" value="${esc(value)}" placeholder="${esc(placeholder)}" spellcheck="true"/></div>`;
const area=(label,key,value,scope='site',placeholder='')=>`<div class="field"><label>${esc(label)}</label><textarea data-${scope}-field="${esc(key)}" placeholder="${esc(placeholder)}" rows="3">${esc(value)}</textarea></div>`;
const numeric=(label,key,value,scope,min=0,max=100)=>`<div class="field"><label>${esc(label)}</label><input type="number" data-${scope}-field="${esc(key)}" min="${min}" max="${max}" value="${esc(value)}"/></div>`;
const select=(label,key,value,opts,scope='block')=>`<div class="field"><label>${esc(label)}</label><select data-${scope}-field="${esc(key)}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const BLOCK=(type,props={},style={})=>({id:id(),type,props,style:{paddingY:58,surface:'plain',...style}});
const defaultFreeformNodes=()=>[
 {id:id(),kind:'note',text:'Discover the problem',layout:{desktop:{x:7,y:24,w:27,h:45},tablet:{x:6,y:24,w:28,h:44},mobile:{x:9,y:8,w:82,h:21}}},
 {id:id(),kind:'label',text:'Build with purpose.',layout:{desktop:{x:38,y:34,w:40,h:30},tablet:{x:37,y:36,w:48,h:30},mobile:{x:8,y:39,w:84,h:19}}},
 {id:id(),kind:'pill',text:'Learn · Improve · Ship',layout:{desktop:{x:56,y:77,w:33,h:14},tablet:{x:52,y:77,w:39,h:14},mobile:{x:15,y:70,w:70,h:13}}}
];
function defaultBlock(type){
 switch(type){
 case 'Hero':return BLOCK(type,{eyebrow:'HELLO, I AM',primaryAction:'Explore my projects'}, {paddingY:78});
 case 'SectionHeading':return BLOCK(type,{eyebrow:'SELECTED WORK',title:'Work that tells a story.',description:'Practical ideas turned into useful outcomes.'});
 case 'ProjectGrid':return BLOCK(type,{title:'Selected projects',description:'A collection of work across engineering, data and practical problem solving.',columns:2,maxProjects:6});
 case 'About':return BLOCK(type,{title:'A little about me',showSkills:true},{surface:'soft'});
 case 'SkillCloud':return BLOCK(type,{title:'Technologies I work with'},{paddingY:48});
 case 'Freeform':return BLOCK(type,{title:'How I approach problems',height:{desktop:270,tablet:290,mobile:410},nodes:defaultFreeformNodes()});
 case 'Contact':return BLOCK(type,{eyebrow:'SAY HELLO',title:'Have something to build?',description:'I am always interested in thoughtful technical projects and collaboration.'},{paddingY:70,surface:'soft'});
 case 'Text':return BLOCK(type,{title:'Your section heading',text:'Tell your story here. Select this section to edit the heading and copy.'},{paddingY:48});
 case 'Image':return BLOCK(type,{src:'',caption:'Your image caption',height:240},{paddingY:34});
 case 'Spacer':return BLOCK(type,{height:65},{paddingY:0});
 default:return defaultBlock('Text');
 }
}
function seed(){return {
 schemaVersion:1,site:{name:'Vaibhav Admane',role:'Applied AI & Data Analytics Developer',heroOne:'Making data useful.',heroTwo:'Building AI that works.',intro:'From document intelligence and predictive models to analytics dashboards and business automation, I enjoy building the complete path from a problem to something people can use.',about:'I work across applied AI, data analytics and business application development. I enjoy connecting technical thinking with practical outcomes, from developing predictive models and data pipelines to creating tools people can actually use.',email:'vaibhavadmane03@gmail.com',github:'https://github.com/Vaibhav-153',linkedin:'https://www.linkedin.com/in/vaibhav-admane-15rtj',skills:['Python','SQL','Machine Learning','RAG','FastAPI','Power BI','Streamlit','Zoho CRM']},
 projects:[
 {id:'bearing',title:'Bearing Lifetime Prediction',category:'Machine Learning',summary:'An experimental predictive-maintenance application built with vibration data, XGBoost, FastAPI and Streamlit.',tech:['Python','XGBoost','FastAPI'],art:'wave',github:'https://github.com/Vaibhav-153/Bearing-Lifetime-Prediction',demo:''},
 {id:'agriculture',title:'Indian Agriculture Analytics',category:'Data Analytics',summary:'An interactive Power BI analysis exploring Indian crop production, trends, regions and seasons.',tech:['Power BI','Power Query','Analytics'],art:'bars',github:'https://github.com/Vaibhav-153/indian-agriculture-powerbi-analysis',demo:''},
 {id:'medical',title:'Multi-Disease ML Demonstrator',category:'Machine Learning',summary:'An educational Streamlit interface for exploring the outputs of classification models. Not a medical diagnostic tool.',tech:['Python','Scikit-learn','Streamlit'],art:'network',github:'https://github.com/Vaibhav-153/Multi-Disease-Prediction-Web-App',demo:''}
 ],
 template:'minimal',pages:[
 {id:'home',title:'Home',slug:'/',blocks:[defaultBlock('Hero'),defaultBlock('ProjectGrid'),defaultBlock('About'),defaultBlock('Freeform'),defaultBlock('Contact')]},
 {id:'projects',title:'Projects',slug:'/projects',blocks:[BLOCK('SectionHeading',{eyebrow:'PORTFOLIO / WORK',title:'A closer look at my projects.',description:'Ideas, implementations and lessons from building practical technology.'},{paddingY:68}),BLOCK('ProjectGrid',{title:'All projects',description:'Select a project to see the source code.',columns:2,maxProjects:99},{paddingY:38}),defaultBlock('Contact')]}
 ]
};}
function safeLoad(key){try{const raw=localStorage.getItem(key);if(!raw)return null;const data=JSON.parse(raw);if(!data||data.schemaVersion!==1||!data.site||!Array.isArray(data.pages)||!Array.isArray(data.projects))return null;return data;}catch{return null}}
let doc=safeLoad(STORAGE)||seed();
let history=[JSON.stringify(doc)];let historyCursor=0;let lastHistory={key:'',time:0};let saveTimer=0;
let ui={tab:'elements',page:'home',device:'desktop',selectedBlock:null,selectedNode:null,selectedProject:null,search:'',modal:'',save:'Saved locally',sideOpen:false,inspectorOpen:false,dragging:null};
const params=new URLSearchParams(location.search);
const mode=params.get('mode')||'edit';
function pageOf(document=doc){return document.pages.find(p=>p.id===ui.page)||document.pages[0]}
const selectedBlock=()=>pageOf().blocks.find(b=>b.id===ui.selectedBlock)||null;
const selectedNode=()=>selectedBlock()?.props?.nodes?.find(n=>n.id===ui.selectedNode)||null;
function makeHistory(key=''){const serialized=JSON.stringify(doc);if(history[historyCursor]===serialized)return;const now=Date.now();if(key && lastHistory.key===key && now-lastHistory.time<750 && historyCursor===history.length-1){history[historyCursor]=serialized;}else{history=history.slice(0,historyCursor+1);history.push(serialized);if(history.length>75)history.shift();historyCursor=history.length-1;}lastHistory={key,time:now};}
function commit(fn,options={}){const before=JSON.stringify(doc);fn();if(JSON.stringify(doc)===before)return;makeHistory(options.key||'');scheduleSave();if(options.quick){renderCanvas();updateToolbar();}else renderStudio();}
function updateToolbar(){const undo=document.querySelector('[data-action="undo"]'),redo=document.querySelector('[data-action="redo"]');if(undo)undo.disabled=historyCursor<=0;if(redo)redo.disabled=historyCursor>=history.length-1;const lbl=document.getElementById('save-label');if(lbl)lbl.textContent=ui.save;const node=document.getElementById('canvas-bottom-message');if(node)node.textContent=`${pageOf().blocks.length} sections · ${ui.device} layout`;}
function scheduleSave(){ui.save='Saving…';updateToolbar();clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(doc));ui.save='Saved locally';}catch{ui.save='Storage full';toast('Local storage is full. Export your work and remove large images.',true)}updateToolbar();},290)}
function toast(message,error=false){const stack=document.getElementById('toast-stack')||document.body;const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=ICON(error?'info':'check')+`<span>${esc(message)}</span>`;stack.appendChild(el);setTimeout(()=>el.remove(),4400)}
function projectSVG(art){if(art==='wave')return `<svg viewBox="0 0 450 170" fill="none" aria-hidden="true"><path d="M0 138h450M0 95h450M0 52h450" stroke="#c6cee6" stroke-width="1"/><path d="M0 120c20-2 30-15 50-21s34 26 56 5 36-53 61-41 36 48 59 29 43-62 68-41 36 41 59 7 51-24 97-35" stroke="#5975bd" stroke-width="4" stroke-linecap="round"/><circle cx="353" cy="61" r="7" fill="#f8fafc" stroke="#5975bd" stroke-width="4"/><rect x="19" y="14" width="81" height="21" rx="5" fill="#d6dff2"/><rect x="26" y="22" width="54" height="5" rx="2" fill="#7893c8"/></svg>`;
 if(art==='bars')return `<svg viewBox="0 0 450 170" fill="none" aria-hidden="true"><path d="M25 140H430" stroke="#dfbcb1"/><rect x="60" y="83" width="47" height="57" rx="7" fill="#b3816f"/><rect x="130" y="50" width="47" height="90" rx="7" fill="#cb9d8c"/><rect x="200" y="73" width="47" height="67" rx="7" fill="#a96e60"/><rect x="270" y="23" width="47" height="117" rx="7" fill="#ca8f7b"/><rect x="340" y="43" width="47" height="97" rx="7" fill="#b47a6b"/><path d="M84 68c50-45 95-5 135-32s80 9 155-19" stroke="#e7c7b7" stroke-width="3" stroke-dasharray="6 5"/></svg>`;
 return `<svg viewBox="0 0 450 170" fill="none" aria-hidden="true"><path d="M79 128 161 60 255 116 356 36M161 60 276 28 356 36M79 128l167 12 110-104" stroke="#9cbdb2" stroke-width="2"/><circle cx="79" cy="128" r="23" fill="#cae0d9" stroke="#6d9b8f" stroke-width="3"/><circle cx="161" cy="60" r="24" fill="#d2e8df" stroke="#6d9b8f" stroke-width="3"/><circle cx="255" cy="116" r="19" fill="#cae0d9" stroke="#6d9b8f" stroke-width="3"/><circle cx="356" cy="36" r="22" fill="#daeae3" stroke="#6d9b8f" stroke-width="3"/><circle cx="276" cy="28" r="10" fill="#6d9b8f"/><circle cx="246" cy="140" r="11" fill="#6d9b8f"/></svg>`;}
function projectCard(p){return `<article class="p-project-card"><div class="p-project-art art-${['wave','bars','network'].includes(p.art)?p.art:'network'}">${projectSVG(p.art)}</div><div class="p-project-body"><span class="p-project-category">${esc(p.category)}</span><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="p-tags">${(p.tech||[]).slice(0,4).map(s=>`<span class="p-tag">${esc(s)}</span>`).join('')}</div><div class="p-project-links">${webUrl(p.github)?`<a href="${esc(webUrl(p.github))}" target="_blank" rel="noopener noreferrer">Source code</a>`:''}${webUrl(p.demo)?`<a href="${esc(webUrl(p.demo))}" target="_blank" rel="noopener noreferrer">Live demo</a>`:''}</div></div></article>`}
function blockSurface(block){return block.style?.surface==='soft'?'var(--ps-soft)':block.style?.surface==='contrast'?'var(--ps-surface)':'transparent';}
function renderBlock(document,block,editable,device){
 const p=block.props||{},s=document.site,pad=clamp(block.style?.paddingY??55,0,150),sectionStyle=`style="--block-pad:${pad}px;--block-bg:${blockSurface(block)}"`;
 let body='';
 switch(block.type){
 case 'Hero':body=`<section class="p-section" ${sectionStyle}><div class="p-hero"><div class="p-hero-copy"><div class="p-eyebrow">${esc(p.eyebrow||'HELLO, I AM')} ${esc(s.name)}</div><h1>${esc(s.heroOne)}<em>${esc(s.heroTwo)}</em></h1><p class="p-role">${esc(s.role)}</p><p class="p-bodycopy">${esc(s.intro)}</p><div class="p-hero-actions"><a href="#portfolio-projects" class="p-btn">${esc(p.primaryAction||'See my work')}</a><a class="p-btn secondary" href="${esc(mailUrl(s.email)||'#contact')}">Get in touch</a></div><div class="p-socials"><span>FIND ME ON</span>${webUrl(s.github)?`<a href="${esc(webUrl(s.github))}" target="_blank" rel="noopener noreferrer">GitHub</a>`:''}${webUrl(s.linkedin)?`<a href="${esc(webUrl(s.linkedin))}" target="_blank" rel="noopener noreferrer">LinkedIn</a>`:''}</div></div><div class="p-illustration"><div class="p-illustration-card"><div class="p-illust-top"><div class="mini-logo">D</div> FIELD NOTES <span class="p-status">● EXPERIMENTING</span></div><div class="p-illust-content"><div class="p-illust-label">A practical approach</div><div class="p-illust-heading">From a question<br/>to a working solution.</div><div class="p-step-list"><div class="p-step"><strong>Explore</strong><span>Understand</span></div><div class="p-step"><strong>Develop</strong><span>Build</span></div><div class="p-step"><strong>Deliver</strong><span>Improve</span></div></div><div class="p-wave-panel"><svg viewBox="0 0 390 92" preserveAspectRatio="none" aria-hidden="true"><path d="M0 21H390M0 47H390M0 74H390" stroke="var(--ps-stroke)"/><path d="M0 74Q30 64 55 65T120 60T185 46T250 42T310 30T390 7" stroke="var(--ps-accent)" stroke-width="2.8" fill="none"/><path d="M0 74Q30 64 55 65T120 60T185 46T250 42T310 30T390 7V92H0Z" fill="var(--ps-accent)" opacity=".09"/></svg></div></div></div></div></div></section>`;break;
 case 'SectionHeading':body=`<section class="p-section" ${sectionStyle}><div class="p-section-heading"><div class="p-eyebrow">${esc(p.eyebrow||'OVERVIEW')}</div><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p></div></section>`;break;
 case 'ProjectGrid':{const count=clamp(p.maxProjects??6,1,100),projects=document.projects.slice(0,count);body=`<section id="portfolio-projects" class="p-section" ${sectionStyle}><div class="p-section-heading"><div class="p-eyebrow">SELECTED WORK</div><h2>${esc(p.title||'Selected projects')}</h2><p>${esc(p.description||'Projects and experiments.')}</p></div><div class="p-project-grid" style="--project-cols:${clamp(p.columns||2,1,3)}">${projects.length?projects.map(projectCard).join(''):'<p>No projects yet. Add one in the Content panel.</p>'}</div></section>`;break;}
 case 'About':body=`<section class="p-section" ${sectionStyle}><div class="p-about"><div><div class="p-eyebrow">A LITTLE CONTEXT</div><h2>${esc(p.title||'A little about me')}</h2></div><div class="p-about-details"><p>${esc(s.about)}</p>${p.showSkills!==false?`<div class="p-skills">${(s.skills||[]).slice(0,8).map(t=>`<span class="p-skill">${esc(t)}</span>`).join('')}</div>`:''}</div></div></section>`;break;
 case 'SkillCloud':body=`<section class="p-section" ${sectionStyle}><div class="p-section-heading"><div class="p-eyebrow">TOOLKIT</div><h2>${esc(p.title||'Technical skills')}</h2></div><div class="p-skills">${(s.skills||[]).map(t=>`<span class="p-skill">${esc(t)}</span>`).join('')}</div></section>`;break;
 case 'Freeform':{let height=clamp((p.height||{})[device]||270,180,600);body=`<section class="p-section" ${sectionStyle}><h2 class="p-freeform-title">${esc(p.title||'Freeform section')}</h2><div class="freeform-stage" data-block-stage="${esc(block.id)}" data-editable="${editable}" style="--ff-height:${height}px">${(p.nodes||[]).map(n=>{const pos=(n.layout||{})[device]||(n.layout||{}).desktop||{x:5,y:5,w:24,h:20};return `<div class="ff-node kind-${['note','label','pill'].includes(n.kind)?n.kind:'note'} ${editable&&ui.selectedNode===n.id?'selected':''}" data-freeform-node="${esc(n.id)}" style="left:${clamp(pos.x,0,100)}%;top:${clamp(pos.y,0,100)}%;width:${clamp(pos.w,4,100)}%;height:${clamp(pos.h,4,100)}%"><span>${esc(n.text)}</span>${editable?`<span class="node-resize" data-resize-handle="${esc(n.id)}"></span>`:''}</div>`}).join('')}</div>${editable?`<div class="ff-help">Select an item to drag or resize it. Adjust positions separately for each device.</div>`:''}</section>`;break;}
 case 'Contact':body=`<section id="contact" class="p-section p-contact" ${sectionStyle}><div class="p-eyebrow">${esc(p.eyebrow||'CONTACT')}</div><h2>${esc(p.title||'Have something to build?')}</h2><p>${esc(p.description||'Let’s connect.')}</p><a class="p-btn" href="${esc(mailUrl(s.email)||'#contact')}">Email me</a></section>`;break;
 case 'Text':body=`<section class="p-section p-textblock" ${sectionStyle}><h2>${esc(p.title)}</h2><p>${esc(p.text)}</p></section>`;break;
 case 'Image':{const src=url(p.src||'');body=`<section class="p-section" style="--block-pad:${pad}px;--block-bg:${blockSurface(block)};--image-h:${clamp(p.height||240,80,650)}px">${src?`<img class="p-inline-image" src="${esc(src)}" alt="${esc(p.caption||'Portfolio image')}" loading="lazy"/>`:`<div class="image-placeholder">${ICON('image')}<span>Upload an image or paste an image URL</span></div>`}<div class="p-image-caption">${esc(p.caption||'')}</div></section>`;break;}
 case 'Spacer':body=`<div style="height:${clamp(p.height||60,8,240)}px" aria-hidden="true"></div>`;break;
 default:return '';
 }
 if(!editable)return body;
 return `<div class="block-shell ${ui.selectedBlock===block.id?'selected':''}" data-block-id="${esc(block.id)}"><div class="block-toolbar">${esc(BLOCK_INFO[block.type]?.title||block.type)}</div>${body}</div>`;
}
function renderSite(document,pageId,editable=false,device='desktop'){
 const page=document.pages.find(p=>p.id===pageId)||document.pages[0];if(!page)return '';
 const initials=document.site.name.split(/\s+/).map(t=>t[0]||'').slice(0,2).join('').toUpperCase();
 const navPrefix=mode==='edit'?'?mode=preview':`?mode=${mode==='public'?'public':'preview'}`;
 const menu=editable?`<a href="#portfolio-projects">Projects</a><a href="#contact">Contact</a>`:`<a href="${navPrefix}&page=home">Home</a><a href="${navPrefix}&page=projects">Projects</a><a href="${esc(mailUrl(document.site.email)||'#contact')}" class="p-nav-cta">Contact</a>`;
 const nav=`<div class="p-nav"><div class="p-brand">${esc(initials)}<span>.</span></div><nav class="p-navlinks">${menu}</nav></div>`;
 const blocks=page.blocks.map((b,i)=>(editable?`<div class="drop-slot" data-drop-index="${i}"></div>`:'')+renderBlock(document,b,editable,device)).join('')+(editable?`<div class="drop-slot" data-drop-index="${page.blocks.length}"></div>`:'');
 const footer=`<footer class="p-footer"><span>© ${new Date().getFullYear()} ${esc(document.site.name)}.</span><span>Created with Devfolio Studio</span></footer>`;
 return `<div class="portfolio-site template-${['minimal','midnight','grid'].includes(document.template)?document.template:'minimal'}">${nav}${blocks}${footer}</div>`;
}
function renderTopbar(){return `<header class="topbar"><div class="brand"><div class="brand-mark">D<i>.</i></div><div class="brand-name">devfolio <span>studio</span></div><span class="brand-beta">PHASE 0</span></div><div class="breadcrumb">Workspace ${ICON('chevron')} <strong>Visual Designer</strong></div><div class="top-actions"><button class="icon-button" data-action="undo" aria-label="Undo" title="Undo" ${historyCursor===0?'disabled':''}>${ICON('undo')}</button><button class="icon-button" data-action="redo" aria-label="Redo" title="Redo" ${historyCursor>=history.length-1?'disabled':''}>${ICON('redo')}</button><div class="toolbar-div"></div><div class="device-tabs" role="group" aria-label="Preview size">${[['desktop','desktop','Desktop'],['tablet','tablet','Tablet'],['mobile','mobile','Mobile']].map(([d,ic,l])=>`<button class="icon-button ${ui.device===d?'active':''}" data-action="device" data-value="${d}" title="${l}" aria-label="${l}" aria-pressed="${ui.device===d}">${ICON(ic)}</button>`).join('')}</div><div class="toolbar-div"></div><span class="save-status"><span class="save-dot"></span><span id="save-label">${esc(ui.save)}</span></span><button class="btn small" data-action="preview">${ICON('eye')} Preview</button><button class="btn primary small" data-action="publish">Publish demo</button><button class="icon-button inspector-mobile-toggle" style="display:none" data-action="toggle-inspector" title="Properties" aria-label="Toggle properties">${ICON('settings')}</button></div></header>`;}
function renderRail(){return `<nav class="nav-rail" aria-label="Editor tools">${[['elements','layout','Blocks'],['layers','layers','Layers'],['content','user','Content'],['templates','palette','Design']].map(([tab,icon,label])=>`<button class="rail-tab ${ui.tab===tab?'active':''}" data-action="tab" data-value="${tab}" aria-label="${label}" aria-pressed="${ui.tab===tab}">${ICON(icon)}<span>${label}</span></button>`).join('')}<button class="rail-tab rail-bottom ${ui.tab==='help'?'active':''}" data-action="tab" data-value="help" aria-label="Help">${ICON('help')}<span>Help</span></button></nav>`;}
const panelHeader=(eyebrow,title,sub)=>`<div class="panel-header"><div class="section-label">${esc(eyebrow)}</div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div>`;
function renderElementsPanel(){const results=Object.entries(BLOCK_INFO).filter(([type,x])=>(`${x.title} ${x.group} ${x.hint}`).toLowerCase().includes(ui.search.toLowerCase()));return panelHeader('COMPOSE','Elements','Click an element to add it, or drag it onto the page.')+`<div class="panel-scroll"><div class="search-wrap">${ICON('grid')}<input id="block-search" value="${esc(ui.search)}" placeholder="Search components..." aria-label="Search components" /></div>${['Portfolio','Basic','Layout'].map(group=>{const arr=results.filter(([,x])=>x.group===group);if(!arr.length)return '';return `<div class="panel-section"><div class="panel-section-title">${esc(group)} components <span>${arr.length}</span></div><div class="tile-grid">${arr.map(([type,x])=>`<button class="block-tile" draggable="true" data-add-block="${esc(type)}" title="${esc(x.hint)}">${ICON(x.icon)}<span>${esc(x.title)}</span></button>`).join('')}</div></div>`}).join('')}<div class="tip-card"><strong>Build it your way</strong>Start with a section, then select it in the canvas to change spacing and content. Freeform lets you drag cards inside a responsive area.</div></div>`;}
function renderLayersPanel(){const p=pageOf();return panelHeader('PAGE STRUCTURE','Layers','Select and reorder the sections on your page.')+`<div class="panel-scroll"><div class="panel-section-title">${esc(p.title)} · ${p.blocks.length} sections</div>${p.blocks.map((b,i)=>`<div class="layer-item ${ui.selectedBlock===b.id?'selected':''}" data-layer-id="${esc(b.id)}" draggable="true" tabindex="0" role="button" aria-label="Select ${esc(BLOCK_INFO[b.type]?.title||b.type)}">${ICON(BLOCK_INFO[b.type]?.icon||'grid')}<span>${esc(BLOCK_INFO[b.type]?.title||b.type)}</span><span style="margin-left:auto;font-size:10px">${String(i+1).padStart(2,'0')}</span></div>${b.type==='Freeform'&&ui.selectedBlock===b.id?(b.props.nodes||[]).map(n=>`<div class="layer-item layer-child ${ui.selectedNode===n.id?'selected':''}" data-select-node="${esc(n.id)}">${ICON('move')}<span>${esc(n.text)}</span></div>`).join(''):''}`).join('')}<button class="btn" style="width:100%;margin-top:17px" data-action="tab" data-value="elements">${ICON('plus')} Add another section</button><p class="inspector-note" style="margin-top:15px">Drag layers to reorder. For keyboard access, select a layer and use the Move buttons in the inspector.</p></div>`;}
function renderContentPanel(){let pr=doc.projects.find(p=>p.id===ui.selectedProject);return panelHeader('YOUR DETAILS','Portfolio content','Update information once. Every connected component will reflect the changes.')+`<div class="panel-scroll"><div class="panel-section"><div class="panel-section-title">Identity</div>${txt('Full name','name',doc.site.name)}${txt('Professional title','role',doc.site.role)}${txt('Headline line 1','heroOne',doc.site.heroOne)}${txt('Headline line 2','heroTwo',doc.site.heroTwo)}${area('Hero introduction','intro',doc.site.intro)}${area('About description','about',doc.site.about)}</div><div class="panel-section"><div class="panel-section-title">Contact and skills</div>${txt('Email address','email',doc.site.email)}${txt('GitHub URL','github',doc.site.github)}${txt('LinkedIn URL','linkedin',doc.site.linkedin)}${area('Skills (comma separated)','skills',(doc.site.skills||[]).join(', '))}</div><div class="panel-section"><div class="panel-section-title">Projects <button class="btn small" data-action="add-project">${ICON('plus')} Add</button></div>${doc.projects.map(p=>`<div class="project-list-item ${pr&&pr.id===p.id?'active':''}" data-project-select="${esc(p.id)}"><div class="project-bubble">${esc((p.title||'P')[0])}</div><div style="min-width:0"><div class="project-name">${esc(p.title)}</div><div class="project-caption">${esc(p.category)}</div></div>${ICON('chevron','project-chevron')}</div>`).join('')||'<p class="inspector-note">No projects yet.</p>'}</div>${pr?`<div class="panel-section" id="project-editor"><div class="panel-section-title">Edit selected project</div>${txt('Project name','title',pr.title,'project')}${txt('Category','category',pr.category,'project')}${area('Summary','summary',pr.summary,'project')}${txt('Technology tags (comma separated)','tech',(pr.tech||[]).join(', '),'project')}${txt('GitHub URL','github',pr.github||'','project')}${txt('Live demo URL','demo',pr.demo||'','project')}${select('Cover illustration','art',pr.art,[['wave','Signal wave'],['network','Network graph'],['bars','Analytics bars']],'project')}<button class="btn small danger" data-action="delete-project">${ICON('trash')} Delete project</button></div>`:''}<div class="tip-card"><strong>One source of truth</strong>Project cards are connected to this project list. Renaming a project updates it everywhere without rebuilding the layout.</div></div>`;}
function renderTemplatesPanel(){const tpl=[{id:'minimal',name:'Signature Minimal',detail:'Warm white, clean typography and plenty of breathing room.'},{id:'midnight',name:'Midnight Developer',detail:'Quiet dark surfaces with structured technical content.'},{id:'grid',name:'Grid Studio',detail:'Editorial project-first composition and spacious grids.'}];return panelHeader('YOUR STYLE','Design library','Switch styles without losing your projects or page layout.')+`<div class="panel-scroll">${tpl.map(x=>`<button class="template-option ${doc.template===x.id?'selected':''}" data-action="template" data-value="${x.id}"><div class="template-thumb ${x.id}" style="color:${x.id==='midnight'?'#b5caf1':x.id==='grid'?'#547c6a':'#4b607b'}"><div class="thumb-bar"></div><div class="thumb-line"></div><div class="thumb-row"><i></i><i></i></div></div><div class="template-meta"><strong>${x.name}</strong><span>${doc.template===x.id?'Selected':'Choose'}</span></div><p>${x.detail}</p></button>`).join('')}<div class="tip-card"><strong>Safe template switching</strong>Your copy, project data and freeform positions are kept when you change the template. This prototype applies design tokens and composition styles.</div></div>`;}
function renderHelpPanel(){return panelHeader('QUICK START','How to use it','Everything here works in your browser without an account.')+`<div class="panel-scroll"><div class="panel-section"><div class="panel-section-title">In five steps</div>${[['1','Add sections using Elements'],['2','Click a section to edit it'],['3','Switch to Content for your details'],['4','Check desktop, tablet and mobile'],['5','Publish your local demo version']].map(([n,t])=>`<div style="display:flex;gap:12px;align-items:center;margin-bottom:16px;font-size:12px;color:#596a61"><span style="font-size:11px;font-weight:800;background:#eef5ef;color:#397265;border-radius:7px;padding:6px 9px">${n}</span>${t}</div>`).join('')}</div><div class="panel-section"><div class="panel-section-title">Your data</div><div class="mini-actions"><button class="btn small" data-action="export">${ICON('download')} Export JSON</button><button class="btn small" data-action="import">${ICON('upload')} Import JSON</button></div><button class="btn small danger" style="margin-top:9px" data-action="reset">${ICON('trash')} Reset demo</button></div><div class="tip-card"><strong>Prototype only</strong>Data is saved to this browser's local storage. There is no login, database, hosted URL or live publication yet. Phase 0 tests editing behavior and a reusable rendering schema.</div></div>`;}
function renderSidebar(){return ui.tab==='elements'?renderElementsPanel():ui.tab==='layers'?renderLayersPanel():ui.tab==='content'?renderContentPanel():ui.tab==='templates'?renderTemplatesPanel():renderHelpPanel()}
function renderInspector(){const b=selectedBlock(),n=selectedNode();if(!b)return panelHeader('PROPERTIES','Inspector','Select a section or an element to configure it.')+`<div class="inspector-scroll"><div class="empty-state"><div class="empty-icon">${ICON('settings')}</div><h3>Nothing selected</h3><p>Select any section in the page canvas to edit its appearance, content and layout.</p></div><div class="tip-card"><strong>Begin with a block</strong>Choose an element from the left panel and add it to the page, or select one already on the canvas.</div></div>`;
 const page=pageOf(),index=page.blocks.findIndex(x=>x.id===b.id),info=BLOCK_INFO[b.type];
 let fields='';
 if(b.type==='Hero')fields=txt('Small introduction','eyebrow',b.props.eyebrow||'','block')+txt('Main button label','primaryAction',b.props.primaryAction||'','block')+`<div class="tip-card"><strong>Bound to your profile</strong>Hero title, role and description come from the Content panel.</div>`;
 else if(b.type==='SectionHeading')fields=txt('Eyebrow','eyebrow',b.props.eyebrow||'','block')+txt('Heading','title',b.props.title||'','block')+area('Description','description',b.props.description||'','block');
 else if(b.type==='ProjectGrid')fields=txt('Heading','title',b.props.title||'','block')+area('Description','description',b.props.description||'','block')+select('Desktop columns','columns',b.props.columns??2,[[1,'1 column'],[2,'2 columns'],[3,'3 columns']])+numeric('Maximum project cards','maxProjects',b.props.maxProjects??6,'block',1,100)+`<div class="tip-card"><strong>Live content binding</strong>Cards are generated from the Projects list. Update cards in the Content panel.</div>`;
 else if(b.type==='About')fields=txt('Title','title',b.props.title||'','block')+select('Show skills','showSkills',String(b.props.showSkills!==false),[['true','Show'],['false','Hide']])+`<div class="tip-card">Edit your About text and skills in the Content panel.</div>`;
 else if(b.type==='SkillCloud')fields=txt('Heading','title',b.props.title||'','block')+`<div class="tip-card">Skill tags are connected to the Content panel.</div>`;
 else if(b.type==='Contact')fields=txt('Eyebrow','eyebrow',b.props.eyebrow||'','block')+txt('Heading','title',b.props.title||'','block')+area('Description','description',b.props.description||'','block');
 else if(b.type==='Text')fields=txt('Heading','title',b.props.title||'','block')+area('Body text','text',b.props.text||'','block');
 else if(b.type==='Image')fields=txt('Image URL','src',b.props.src||'','block','https://example.com/image.jpg')+`<div class="field"><label>Or upload an image (up to 1 MB)</label><input type="file" data-image-upload="true" accept="image/png,image/jpeg,image/webp" /></div>`+txt('Alt text / caption','caption',b.props.caption||'','block')+numeric('Image height (px)','height',b.props.height||240,'block',80,650);
 else if(b.type==='Spacer')fields=numeric('Space height (px)','height',b.props.height||60,'block',8,240);
 else if(b.type==='Freeform'){fields=txt('Section heading','title',b.props.title||'','block')+numeric(`Stage height on ${ui.device} (px)`,'height',(b.props.height||{})[ui.device]||270,'freeform-height',180,600)+`<div class="panel-section-title">Freeform items</div><div class="mini-actions" style="margin-bottom:12px"><button class="btn small" data-action="add-node" data-value="note">${ICON('plus')} Card</button><button class="btn small" data-action="add-node" data-value="label">${ICON('plus')} Text</button><button class="btn small" data-action="add-node" data-value="pill">${ICON('plus')} Pill</button></div><p class="inspector-note">Drag an item in the canvas, then use its corner handle to resize. Switch devices to adjust independent positions.</p>`;if(n){const pos=n.layout[ui.device]||n.layout.desktop||{x:0,y:0,w:30,h:20};fields+=`<hr class="inspector-divider"/><div class="inspector-heading">Selected item · ${esc(n.kind)}</div>`+txt('Text','text',n.text,'node')+`<div class="field-row">${numeric('Left (%)','x',pos.x,'nodepos')}${numeric('Top (%)','y',pos.y,'nodepos')}${numeric('Width (%)','w',pos.w,'nodepos',4,100)}${numeric('Height (%)','h',pos.h,'nodepos',4,100)}</div><button class="btn small danger" data-action="delete-node">${ICON('trash')} Remove item</button>`;}}
 const general= b.type==='Spacer'?'':`<hr class="inspector-divider"/><div class="inspector-heading">Layout & appearance</div><div class="field"><label>Section spacing</label><div class="range-row"><input type="range" min="0" max="150" data-block-style="paddingY" value="${clamp(b.style?.paddingY??55,0,150)}"/><span class="range-value">${clamp(b.style?.paddingY??55,0,150)}px</span></div></div>`+select('Surface','surface',b.style?.surface||'plain',[['plain','Plain'],['soft','Soft contrast'],['contrast','Card surface']],'style');
 const header=panelHeader('SELECTED SECTION',info?.title||b.type,'Adjust this section and its behavior.');
 const move=`<div class="property-button-list"><button class="btn small" data-action="move-block" data-value="up" ${index===0?'disabled':''}>${ICON('arrows-up-down')} Move up</button><button class="btn small" data-action="move-block" data-value="down" ${index===page.blocks.length-1?'disabled':''}>${ICON('arrows-up-down')} Move down</button><button class="btn small" data-action="duplicate-block">${ICON('copy')} Duplicate</button><button class="btn small danger" data-action="delete-block">${ICON('trash')} Delete</button></div>`;
 return header+`<div class="inspector-scroll"><div class="inspector-heading">Content</div>${fields}${general}<hr class="inspector-divider"/><div class="inspector-heading">Section actions</div>${move}</div>`;
}
function renderStudio(){const root=document.getElementById('app');root.innerHTML=`<div class="studio ${ui.sideOpen?'side-open':''} ${ui.inspectorOpen?'inspector-open':''}">${renderTopbar()}<div class="workspace-layout">${renderRail()}<aside class="side-panel" id="sidebar">${renderSidebar()}</aside><main class="workspace"><div class="workspace-head"><div class="workspace-heading"><div><h1>${esc(pageOf().title)} canvas</h1><p>Design your pages without writing code</p></div></div><select class="page-select" id="page-select" aria-label="Select page">${doc.pages.map(p=>`<option value="${esc(p.id)}" ${ui.page===p.id?'selected':''}>${esc(p.title)} page</option>`).join('')}</select></div><div class="workspace-canvas" id="workspace-canvas"><div class="canvas-shell" id="canvas-shell" data-device="${ui.device}"><div class="browser-chrome"><span class="browser-dots"><i></i><i></i><i></i></span><span class="browser-path">yourname.devfoliostudio.com${ui.page==='projects'?'/projects':''}</span><span class="browser-indicator">${ui.device} preview</span></div><div class="canvas-root" id="canvas-root"></div></div></div><div class="canvas-bottom"><span><span class="status-light"></span> Local browser prototype</span><span id="canvas-bottom-message">${pageOf().blocks.length} sections · ${ui.device} layout</span></div></main><aside class="inspector" id="inspector">${renderInspector()}</aside></div></div><div class="toast-stack" id="toast-stack"></div><input type="file" id="import-file" accept="application/json,.json" hidden/>${renderModal()}`;renderCanvas();}
function renderCanvas(){const shell=document.getElementById('canvas-shell'),root=document.getElementById('canvas-root');if(!shell||!root)return;shell.dataset.device=ui.device;root.innerHTML=renderSite(doc,ui.page,true,ui.device);const previewLabel=shell.querySelector('.browser-indicator');if(previewLabel)previewLabel.textContent=ui.device+' preview';}
function renderModal(){if(!ui.modal)return '';const m=ui.modal;const demoUrl=(location.protocol==='about:'?'?mode=public&page=home':new URL('?mode=public&page=home',location.href).href);if(m==='publish')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="status-pill">${ICON('check')} READY FOR LOCAL DEMO</div><h2 id="dialog-title" style="margin-top:15px">Publish a demo version</h2><p>This creates a frozen snapshot stored in your browser. It will appear in the public-preview mode here, but <strong>it does not deploy your website to the internet.</strong></p><div class="modal-check">${ICON('check')} ${doc.pages.length} pages included</div><div class="modal-check">${ICON('check')} ${doc.projects.length} projects connected</div><div class="modal-check">${ICON('check')} ${esc(doc.template)} design selected</div><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-publish">Publish local snapshot</button></div></div></div>`;
 if(m==='published')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="status-pill">${ICON('check')} SNAPSHOT CREATED</div><h2 id="dialog-title" style="margin-top:15px">Demo version is ready</h2><p>Your current layout and content are saved separately from the draft. You can continue editing without affecting the demo-public version.</p><div class="modal-code">${esc(demoUrl)}</div><p style="margin-top:11px;font-size:11px">Local browser URL only. Not a shareable internet link.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Back to editor</button><button class="btn primary" data-action="open-published">Open demo website</button></div></div></div>`;
 if(m==='reset')return `<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><h2>Reset your prototype?</h2><p>This will discard your current draft and restore the example portfolio. Export your work first if you need a backup.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-reset">Reset draft</button></div></div></div>`;return '';
}
function refreshPanels(){const left=document.getElementById('sidebar'),right=document.getElementById('inspector');if(left)left.innerHTML=renderSidebar();if(right)right.innerHTML=renderInspector();}
function renderPreviewMode(){let snapshot=mode==='public'?safeLoad(PUBLISHED):doc;if(mode==='public'&&!snapshot){document.body.innerHTML=`<div class="no-published"><div class="modal"><div class="brand-mark" style="margin:auto">D<i>.</i></div><h2 style="margin-top:23px">Nothing published yet</h2><p>Use Publish demo in the visual editor to create a local snapshot first. Live hosting is planned for a later phase.</p><button class="btn primary" id="return-editor">Return to editor</button></div></div>`;document.getElementById('return-editor').addEventListener('click',()=>goEditor());return;}
 const page=params.get('page')||'home';const docPage=snapshot.pages.some(p=>p.id===page)?page:'home';const viewportDevice=()=>window.innerWidth<768?'mobile':window.innerWidth<1024?'tablet':'desktop';let publicDevice=viewportDevice();document.body.className='mode-preview';document.getElementById('app').innerHTML=`<div class="preview-view"><div class="preview-bar"><div class="preview-bar-left"><div class="brand-mark" style="width:29px;height:29px;border-radius:8px;font-size:17px">D<i>.</i></div><div><div class="preview-bar-title">${mode==='public'?'Published demo':'Draft preview'}</div><div class="preview-bar-sub">${mode==='public'?'A local published snapshot — not live on the internet':'Showing your latest local edits'}</div></div></div><button class="btn small" data-action="back-editor">Return to editor</button></div><div class="preview-content" id="published-content">${renderSite(snapshot,docPage,false,publicDevice)}</div><p class="preview-disclaimer">Devfolio Studio Phase 0 · ${mode==='public'?'Local demo-public view':'Private local draft view'} · Not hosted online</p></div>`;
 window.addEventListener('resize',()=>{const next=viewportDevice();if(next!==publicDevice){publicDevice=next;const target=document.getElementById('published-content');if(target)target.innerHTML=renderSite(snapshot,docPage,false,publicDevice);}});
 document.addEventListener('click',e=>{const a=e.target.closest('[data-action="back-editor"]');if(a)goEditor();});
}
function withBlock(fn){const b=selectedBlock();if(b)fn(b);}
function addBlock(type,index=null){if(!ALLOWED.includes(type))return;const b=defaultBlock(type);commit(()=>{const list=pageOf().blocks;list.splice(index===null?list.length:clamp(index,0,list.length),0,b);ui.selectedBlock=b.id;ui.selectedNode=null;ui.inspectorOpen=window.innerWidth<850;});toast(`${BLOCK_INFO[type].title} added`)}
function moveBlock(direction){const list=pageOf().blocks,i=list.findIndex(x=>x.id===ui.selectedBlock),to=i+(direction==='up'?-1:1);if(i<0||to<0||to>=list.length)return;commit(()=>{const [b]=list.splice(i,1);list.splice(to,0,b)});}
function changeDevice(device){if(!['desktop','tablet','mobile'].includes(device))return;ui.device=device;renderStudio();}
function undo(){if(historyCursor<=0)return;historyCursor--;doc=JSON.parse(history[historyCursor]);scheduleSave();renderStudio()}
function redo(){if(historyCursor>=history.length-1)return;historyCursor++;doc=JSON.parse(history[historyCursor]);scheduleSave();renderStudio()}
function importJSON(file){if(!file)return;if(file.size>4*1024*1024){toast('Choose a JSON file smaller than 4 MB.',true);return}const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!validateDocument(imported))throw Error('Unsupported file format');commit(()=>{doc=imported;ui.page=doc.pages[0].id;ui.selectedBlock=null;ui.selectedNode=null;ui.selectedProject=null;});toast('Portfolio JSON imported.')}catch(e){toast('Import failed: '+e.message,true)}};reader.readAsText(file)}
function validateDocument(value){return value&&value.schemaVersion===1&&typeof value.site?.name==='string'&&Array.isArray(value.projects)&&value.projects.length<150&&Array.isArray(value.pages)&&value.pages.length>0&&value.pages.length<=20&&value.pages.every(p=>typeof p.id==='string'&&Array.isArray(p.blocks)&&p.blocks.length<100&&p.blocks.every(b=>ALLOWED.includes(b.type)&&typeof b.id==='string'&&b.props&&typeof b.props==='object'));}
function exportJSON(){const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'});const uri=URL.createObjectURL(blob);const a=document.createElement('a');a.href=uri;a.download='devfolio-layout-draft.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(uri),1500);toast('Draft exported as JSON')}
function goEditor(){const target=new URL(location.href);target.search='';target.hash='';location.href=target.href}
function openLocal(modeName){const target=new URL(location.href);target.searchParams.set('mode',modeName);target.searchParams.set('page',ui.page);target.hash='';window.open(target.href,'_blank','noopener')}
function clickAction(action,value,target){switch(action){
 case 'tab':ui.tab=value;ui.sideOpen=window.innerWidth<=620;renderStudio();break;
 case 'device':changeDevice(value);break;
 case 'undo':undo();break;
 case 'redo':redo();break;
 case 'preview':{try{localStorage.setItem(STORAGE,JSON.stringify(doc))}catch{}openLocal('preview');break}
 case 'publish':ui.modal='publish';renderStudio();break;
 case 'close-modal':ui.modal='';renderStudio();break;
 case 'confirm-publish':try{localStorage.setItem(STORAGE,JSON.stringify(doc));localStorage.setItem(PUBLISHED,JSON.stringify(doc));ui.modal='published';renderStudio();toast('Local demo published.')}catch{toast('Could not save published snapshot.',true)}break;
 case 'open-published':ui.modal='';openLocal('public');renderStudio();break;
 case 'back-editor':goEditor();break;
 case 'move-block':moveBlock(value);break;
 case 'duplicate-block':{const b=selectedBlock();if(!b)return;const copy=clone(b);copy.id=id();if(copy.type==='Freeform')copy.props.nodes=(copy.props.nodes||[]).map(n=>({...n,id:id()}));commit(()=>{const list=pageOf().blocks,i=list.findIndex(x=>x.id===b.id);list.splice(i+1,0,copy);ui.selectedBlock=copy.id;ui.selectedNode=null});toast('Section duplicated');break}
 case 'delete-block':{const b=selectedBlock();if(!b)return;commit(()=>{pageOf().blocks=pageOf().blocks.filter(x=>x.id!==b.id);ui.selectedBlock=null;ui.selectedNode=null});toast('Section deleted. Undo to restore it.');break}
 case 'add-project':{let newId=id();commit(()=>{doc.projects.push({id:newId,title:'New project',category:'Development',summary:'Describe the problem, the solution and what you built.',tech:['Technology'],art:'network',github:'',demo:''});ui.selectedProject=newId;ui.tab='content'});toast('New project added');break}
 case 'delete-project':{let pId=ui.selectedProject;if(!pId)return;commit(()=>{doc.projects=doc.projects.filter(p=>p.id!==pId);ui.selectedProject=null});toast('Project removed from draft');break}
 case 'add-node':{const b=selectedBlock();if(!b||b.type!=='Freeform')return;const kind=['note','label','pill'].includes(value)?value:'note';const node={id:id(),kind,text:kind==='label'?'Your statement':kind==='pill'?'New label':'New content card',layout:{desktop:{x:12,y:16,w:30,h:26},tablet:{x:12,y:16,w:34,h:26},mobile:{x:9,y:8,w:82,h:20}}};commit(()=>{b.props.nodes.push(node);ui.selectedNode=node.id});toast('Freeform item added');break}
 case 'delete-node':{const b=selectedBlock(),n=selectedNode();if(!b||!n)return;commit(()=>{b.props.nodes=b.props.nodes.filter(x=>x.id!==n.id);ui.selectedNode=null});break}
 case 'template':commit(()=>{doc.template=value});toast('Design updated, content preserved');break;
 case 'export':exportJSON();break;
 case 'import':document.getElementById('import-file')?.click();break;
 case 'reset':ui.modal='reset';renderStudio();break;
 case 'confirm-reset':{doc=seed();history=[JSON.stringify(doc)];historyCursor=0;lastHistory={key:'',time:0};ui={...ui,modal:'',page:'home',selectedBlock:null,selectedNode:null,selectedProject:null,tab:'elements',device:'desktop'};scheduleSave();renderStudio();toast('Example portfolio restored');break}
 case 'toggle-inspector':ui.inspectorOpen=!ui.inspectorOpen;renderStudio();break;
 default:break;
}}
function handleFieldInput(t){
 if(t.id==='block-search'){ui.search=t.value;const sidebar=document.getElementById('sidebar');if(sidebar){sidebar.innerHTML=renderSidebar();const input=document.getElementById('block-search');if(input){input.focus();input.setSelectionRange(ui.search.length,ui.search.length)}}return}
 const siteKey=t.getAttribute('data-site-field'),blockKey=t.getAttribute('data-block-field'),projectKey=t.getAttribute('data-project-field'),styleKey=t.getAttribute('data-style-field'),blockStyle=t.getAttribute('data-block-style'),nodeKey=t.getAttribute('data-node-field'),posKey=t.getAttribute('data-nodepos-field'),heightKey=t.getAttribute('data-freeform-height-field');
 const value=t.value;
 if(siteKey){commit(()=>{doc.site[siteKey]=siteKey==='skills'?value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,50):value},{quick:true,key:'site:'+siteKey});return}
 if(projectKey){const p=doc.projects.find(x=>x.id===ui.selectedProject);if(!p)return;commit(()=>{p[projectKey]=projectKey==='tech'?value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,20):value},{quick:true,key:'project:'+p.id+projectKey});return}
 if(blockKey){withBlock(b=>commit(()=>{b.props[blockKey]=blockKey==='showSkills'?value==='true':blockKey==='columns'||blockKey==='maxProjects'||blockKey==='height'?Number(value):value},{quick:true,key:'block:'+b.id+blockKey}));return}
 if(styleKey){withBlock(b=>commit(()=>{b.style[styleKey]=value},{quick:true,key:'style:'+b.id+styleKey}));return}
 if(blockStyle){withBlock(b=>commit(()=>{b.style[blockStyle]=clamp(value,0,150)},{quick:true,key:'blockstyle:'+b.id+blockStyle}));const label=t.parentElement.querySelector('.range-value');if(label)label.textContent=value+'px';return}
 if(nodeKey){withBlock(b=>{const n=selectedNode();if(n)commit(()=>{n[nodeKey]=value},{quick:true,key:'node:'+n.id+nodeKey})});return}
 if(posKey){withBlock(b=>{const n=selectedNode();if(!n)return;commit(()=>{const p=n.layout[ui.device]?clone(n.layout[ui.device]):clone(n.layout.desktop);p[posKey]=clamp(value,0,100);p.w=clamp(p.w,4,100);p.h=clamp(p.h,4,100);p.x=clamp(p.x,0,100-p.w);p.y=clamp(p.y,0,100-p.h);n.layout[ui.device]=p;},{quick:true,key:'nodepos:'+n.id+posKey})});return}
 if(heightKey){withBlock(b=>{if(b.type==='Freeform')commit(()=>{b.props.height[ui.device]=clamp(value,180,600)},{quick:true,key:'height:'+b.id+ui.device})});return}
}
function wireEvents(){
 document.addEventListener('click',e=>{
  const a=e.target.closest('[data-action]');if(a){if(a.disabled)return;clickAction(a.dataset.action,a.dataset.value||'',a);return}
  const add=e.target.closest('[data-add-block]');if(add){addBlock(add.dataset.addBlock);return}
  const pr=e.target.closest('[data-project-select]');if(pr){ui.selectedProject=pr.dataset.projectSelect;renderStudio();setTimeout(()=>document.getElementById('project-editor')?.scrollIntoView({block:'nearest'}),10);return}
  const nodeSelect=e.target.closest('[data-select-node]');if(nodeSelect){ui.selectedNode=nodeSelect.dataset.selectNode;refreshPanels();renderCanvas();return}
  const layer=e.target.closest('[data-layer-id]');if(layer){ui.selectedBlock=layer.dataset.layerId;ui.selectedNode=null;refreshPanels();renderCanvas();return}
  const node=e.target.closest('[data-freeform-node]');if(node){ui.selectedNode=node.dataset.freeformNode;ui.selectedBlock=node.closest('[data-block-id]')?.dataset.blockId||ui.selectedBlock;refreshPanels();renderCanvas();return}
  const block=e.target.closest('#canvas-root [data-block-id]');if(block){ui.selectedBlock=block.dataset.blockId;ui.selectedNode=null;refreshPanels();renderCanvas();return}
  if(e.target.classList.contains('modal-backdrop')){ui.modal='';renderStudio()}
 });
 document.addEventListener('input',e=>handleFieldInput(e.target));
 document.addEventListener('change',e=>{
  const t=e.target;
  if(t.id==='page-select'){ui.page=t.value;ui.selectedBlock=null;ui.selectedNode=null;renderStudio();return}
  if(t.id==='import-file'){importJSON(t.files?.[0]);t.value='';return}
  if(t.hasAttribute('data-image-upload')&&t.files?.[0]){const file=t.files[0];if(file.size>1024*1024){toast('Image is too large for the local prototype (maximum 1 MB).',true);return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Only JPG, PNG and WebP images are accepted.',true);return}const b=selectedBlock();if(!b||b.type!=='Image')return;const reader=new FileReader();reader.onload=()=>{commit(()=>{b.props.src=String(reader.result)});toast('Image added to your draft')};reader.readAsDataURL(file)}
 });
 document.addEventListener('keydown',e=>{
  const inForm=e.target.matches('input, textarea, select, [contenteditable="true"]');
  if((e.ctrlKey||e.metaKey)&&!inForm&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}
  if((e.ctrlKey||e.metaKey)&&!inForm&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}
  if(e.key==='Escape'){if(ui.modal){ui.modal='';renderStudio()}else if(ui.selectedNode||ui.selectedBlock){ui.selectedNode=null;ui.selectedBlock=null;refreshPanels();renderCanvas()}}
  const node=selectedNode();if(node&&!inForm&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const step=e.shiftKey?10:2;commit(()=>{const p=clone(node.layout[ui.device]||node.layout.desktop);if(e.key==='ArrowUp')p.y-=step;if(e.key==='ArrowDown')p.y+=step;if(e.key==='ArrowLeft')p.x-=step;if(e.key==='ArrowRight')p.x+=step;p.x=clamp(p.x,0,100-p.w);p.y=clamp(p.y,0,100-p.h);node.layout[ui.device]=p});}
 });
 let dragging=null;
 document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-add-block],[data-layer-id]');if(!el)return;if(el.hasAttribute('data-add-block'))dragging={type:'new',value:el.dataset.addBlock};else dragging={type:'move',value:el.dataset.layerId};e.dataTransfer?.setData('text/plain',dragging.value);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';});
 document.addEventListener('dragover',e=>{if(!dragging)return;const root=e.target.closest('#canvas-root'),layer=e.target.closest('[data-layer-id]');if(root||layer){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-slot.drag-over').forEach(x=>x.classList.remove('drag-over'));const slot=e.target.closest('[data-drop-index]');if(slot)slot.classList.add('drag-over')}});
 document.addEventListener('drop',e=>{if(!dragging)return;const root=e.target.closest('#canvas-root'),layer=e.target.closest('[data-layer-id]');if(!root&&!layer)return;e.preventDefault();let idx=pageOf().blocks.length;const slot=e.target.closest('[data-drop-index]'),block=e.target.closest('[data-block-id]');if(layer)idx=pageOf().blocks.findIndex(b=>b.id===layer.dataset.layerId);else if(slot)idx=Number(slot.dataset.dropIndex);else if(block){idx=pageOf().blocks.findIndex(b=>b.id===block.dataset.blockId);const rect=block.getBoundingClientRect();if(e.clientY>rect.top+rect.height/2)idx++;}
  const task=dragging;dragging=null;
  if(task.type==='new')addBlock(task.value,idx);
  else{const list=pageOf().blocks;const from=list.findIndex(b=>b.id===task.value);if(from===-1)return;const to=clamp(idx,0,list.length);commit(()=>{const [b]=list.splice(from,1);list.splice(to>from?to-1:to,0,b);ui.selectedBlock=b.id;ui.selectedNode=null});}
 });
 document.addEventListener('dragend',()=>{dragging=null;document.querySelectorAll('.drop-slot.drag-over').forEach(x=>x.classList.remove('drag-over'))});
 let gesture=null;
 document.addEventListener('pointerdown',e=>{
  if(e.button!==0)return;const element=e.target.closest('#canvas-root .ff-node');if(!element)return;const blockEl=element.closest('[data-block-id]'),stage=element.closest('.freeform-stage'),b=pageOf().blocks.find(b=>b.id===blockEl?.dataset.blockId),n=b?.props?.nodes?.find(n=>n.id===element.dataset.freeformNode);if(!b||!n||!stage)return;
  const pos=clone(n.layout[ui.device]||n.layout.desktop);const rect=stage.getBoundingClientRect();ui.selectedBlock=b.id;ui.selectedNode=n.id;gesture={element,blockId:b.id,nodeId:n.id,initial:pos,rect,startX:e.clientX,startY:e.clientY,resizing:!!e.target.closest('[data-resize-handle]'),moved:false,next:clone(pos)};
  document.querySelectorAll('#canvas-root .ff-node').forEach(el=>el.classList.toggle('selected',el===element));refreshPanels();
  e.preventDefault();
 });
 window.addEventListener('pointermove',e=>{if(!gesture)return;const g=gesture;const dx=(e.clientX-g.startX)/g.rect.width*100,dy=(e.clientY-g.startY)/g.rect.height*100;if(Math.abs(dx)+Math.abs(dy)>.4)g.moved=true;const snap=x=>Math.round(x/2)*2;
  let p={...g.initial};if(g.resizing){p.w=clamp(snap(g.initial.w+dx),12,100-p.x);p.h=clamp(snap(g.initial.h+dy),10,100-p.y)}else{p.x=clamp(snap(g.initial.x+dx),0,100-p.w);p.y=clamp(snap(g.initial.y+dy),0,100-p.h)}g.next=p;Object.assign(g.element.style,{left:p.x+'%',top:p.y+'%',width:p.w+'%',height:p.h+'%'})});
 window.addEventListener('pointerup',()=>{if(!gesture)return;const g=gesture;gesture=null;if(g.moved){const b=pageOf().blocks.find(b=>b.id===g.blockId),n=b?.props?.nodes?.find(n=>n.id===g.nodeId);if(n)commit(()=>{n.layout[ui.device]=g.next;ui.selectedBlock=g.blockId;ui.selectedNode=g.nodeId});else renderStudio();}else{ui.selectedBlock=g.blockId;ui.selectedNode=g.nodeId;refreshPanels();renderCanvas();}});
 window.addEventListener('beforeunload',()=>{try{localStorage.setItem(STORAGE,JSON.stringify(doc))}catch{}});
}
if(mode==='edit'){renderStudio();wireEvents();}else if(mode==='public'||mode==='preview'){renderPreviewMode();}else {location.search='';}
})();
